images.text:
$ brainstorming-board prompt --schema board.schema.json --property /topics/0/answer
{
 "ok": true,
 "prompt": {
  "common": {
   "from": "tool/schema-driven/references/writing-rules.json",
   "write": [
    {"id": "one-thing-per-value", "rule": "1つの値に、1つのことだけを書く。", …},
    {"id": "list-as-array", "rule": "3つ以上並ぶものは、1つの文字列に詰めず配列にする。", …}
   ]
  },
  "root": {
   "from": "board.schema.json#",
   "write": [
    {"id": "five-parts", "rule": "承認者が読むのは、問い ・ 答え ・ 完成イメージ ・ 根拠 ・ 採らなかった案の5つだけにする。", …}
   ]
  },
  "property": {
   "from": "board.schema.json#/$defs/answer",
   "read": ["text は1文の決定で、答えの見出しとして太字で出る。", …],
   "write": [
    {"id": "one-sentence-decision", …},
    {"id": "one-meaning-per-item", …},
    {"id": "table-not-prose", …},
    {"id": "keep-points", …}
   ]
  }
 }
}
